/* HITHER-LANDS:tile-anim-state BEGIN */
/*
 * Animated-tile support (Hither Lands).  An animated tile occupies several
 * consecutive atlas columns -- one per frame, frame 0 at the base column the
 * prf maps to.  hl_tile_nframes[(row<<7)|col] is the frame count of a base
 * tile (0/1 == static).  The frame index comes from wall-clock time so water
 * shimmers / torches flicker even while the game waits for input.  This is
 * purely UI-layer state; the game engine is never told that tiles animate.
 */
#define HL_ANIM_TABLE_SIZE (128 * 128)
#define HL_ANIM_FRAME_MS   150u    /* wall-clock ms per animation frame */
static uint8_t *hl_tile_nframes = NULL;
static bool hl_tile_anim_active = false;

static unsigned hl_anim_frame(void)
{
	return (unsigned)(SDL_GetTicks() / HL_ANIM_FRAME_MS);
}

/* Column shift for the current frame of an animated base tile (0 if static). */
static int hl_anim_col_offset(int src_row, int src_col)
{
	unsigned nf;

	if (!hl_tile_anim_active || hl_tile_nframes == NULL) return 0;
	if (src_row < 0 || src_row > 0x7f || src_col < 0 || src_col > 0x7f) return 0;
	nf = hl_tile_nframes[((unsigned)src_row << 7) | (unsigned)src_col];
	if (nf < 2) return 0;
	return (int)(hl_anim_frame() % nf);
}

/*
 * Load <tileset dir>/anim.txt: lines "row:col:frames" (decimal); '#' comments
 * and blank lines are ignored.  A missing file simply means no animated tiles.
 */
static void hl_load_tile_anim(const char *dir)
{
	char path[2048];
	ang_file *fh;
	char line[256];

	hl_tile_anim_active = false;
	if (hl_tile_nframes == NULL) {
		hl_tile_nframes = mem_zalloc(HL_ANIM_TABLE_SIZE * sizeof(uint8_t));
	} else {
		memset(hl_tile_nframes, 0, HL_ANIM_TABLE_SIZE * sizeof(uint8_t));
	}

	path_build(path, sizeof(path), dir, "anim.txt");
	fh = file_open(path, MODE_READ, FTYPE_TEXT);
	if (!fh) return;

	while (file_getl(fh, line, sizeof(line))) {
		int row, col, nf;
		char *s = line;

		while (*s == ' ' || *s == '\t') s++;
		if (*s == '#' || *s == '\0') continue;
		if (sscanf(s, "%d:%d:%d", &row, &col, &nf) != 3) continue;
		if (row < 0 || row > 0x7f || col < 0 || col > 0x7f) continue;
		if (nf < 0 || nf > 255) continue;
		hl_tile_nframes[((unsigned)row << 7) | (unsigned)col] = (uint8_t)nf;
		if (nf >= 2) hl_tile_anim_active = true;
	}

	file_close(fh);
}

/*
 * Idle-time animation tick (called from the SDL2 input-wait loop).  When the
 * frame index has advanced, re-emit the map so animated cells re-bake at their
 * new frame, then present.  Cheap: only does work on a frame boundary.
 */
static void hl_tile_anim_tick(struct my_app *a)
{
	static unsigned hl_last_frame = 0;
	unsigned f;
	term *old;

	if (!hl_tile_anim_active || !character_dungeon) return;

	f = hl_anim_frame();
	if (f == hl_last_frame) return;
	hl_last_frame = f;

	old = Term;
	Term_activate(term_screen);
	Term_redraw();
	Term_activate(old);

	redraw_all_windows(a, false);
}
/* HITHER-LANDS:tile-anim-state END */

