/*
 * Fauna behavior for neutral animals (Hither Lands ecosystem).
 *
 * Skittish (crow, giant white mouse), FRIGHTENED, or low-level:
 * flee when the player gets close.
 * Default: startled (brief fear) if player bumps adjacent.
 * TERRITORIAL: turn hostile if player enters half hearing range -
 * unreachable while neutrality is capped at depth 0 plus the named
 * skittish pair; retained in case the cap is ever raised.
 * CHARM suppresses all proximity aggro for animals.
 */
static void hl_fauna_behavior(struct monster *mon)
{
	int dis;

	if (mon->target.midx != 0) return;
	if (!rf_has(mon->race->flags, RF_ANIMAL)) return;
	if (mon->player_race) return;

	dis = distance(mon->grid, player->grid);

	if (player_has(player, PF_CHARM)) return;

	if (rf_has(mon->race->flags, RF_TERRITORIAL)) {
		if (dis <= mon->race->hearing / 2) {
			mon->target.midx = -1;
			monster_wake(mon, false, 100);
		}
		return;
	}

	if (streq(mon->race->name, "crow") ||
		streq(mon->race->name, "giant white mouse") ||
		rf_has(mon->race->flags, RF_FRIGHTENED) ||
		mon->race->level < player->lev / 2) {
		if (dis <= mon->race->hearing / 3) {
			mon_inc_timed(mon, MON_TMD_FEAR, 5 + randint0(5),
						  MON_TMD_FLG_NOMESSAGE);
		}
		return;
	}

