/* HITHER-LANDS:eco-home-mark BEGIN */
/* Every monster remembers where it spawned so territorial races and pack
 * members can be leashed to a home area (see hl_home_leash).  Upstream set
 * this for RF_TERRITORIAL only. */
mon->home = grid;
/* HITHER-LANDS:eco-home-mark END */

/* HITHER-LANDS:eco-home-leash BEGIN */
/*
 * Home-area leash for territorial races and pack (group) monsters.
 *
 * The eco-* layer removed the sleep that used to hold packs in their spawn
 * blob, so awake wolves/ants/orc-bands scatter via random-walk (RAND_25) and
 * heatmap pursuit with nothing pulling them back.  This tethers a monster to
 * its spawn grid (mon->home): when it has no way to reach the player it heads
 * home, while get_move_advance() transparently overrides the home target on
 * any turn the monster can actually track the player - so a real hunt is never
 * interrupted, and the leash only bites once the monster disengages.
 *
 * Returns true when the monster is being steered home this turn; the caller
 * then cancels innate stagger so the trip isn't wasted on a random step.
 *
 * Replaces the upstream RF_TERRITORIAL block, which was cave-excluded, used a
 * level-sized 5*hearing radius, and clamped target.grid (a per-turn step
 * target) rather than the monster's own position.
 */
static bool hl_home_leash(struct monster *mon)
{
	int radius, dist, i;

	/* Allies and monsters hunting another monster are never leashed. */
	if (mflag_has(mon->mflag, MFLAG_FOLLOWER)) return false;
	if (mon->target.midx > 0) return false;

	/* Only territorial races and live packs (2+ in the group) are leashed. */
	if (!rf_has(mon->race->flags, RF_TERRITORIAL) &&
		monster_primary_group_size(cave, mon) < 2) {
		return false;
	}

	/* Pre-patch savefiles have no home; adopt the current grid. */
	if (loc_is_zero(mon->home)) {
		mon->home = mon->grid;
		return false;
	}

	/* Radius scales with perception so keen animals roam wider.  These two
	 * expressions are the main tuning knob. */
	if (rf_has(mon->race->flags, RF_TERRITORIAL)) {
		radius = MAX(8, mon->race->hearing / 2);
	} else {
		radius = MAX(12, mon->race->hearing);
	}

	dist = distance(mon->home, mon->grid);

	/* Territorial races get a small energy nudge while near home, as upstream
	 * but measured against the leash radius instead of 5 * hearing. */
	if (rf_has(mon->race->flags, RF_TERRITORIAL)) {
		for (i = 5; i > 0; i--) {
			if ((dist * i) > (radius * 5)) break;
		}
		mon->energy += (5 - i);
	}

	/* Outside the home area: aim for home.  If the monster can reach the
	 * player, get_move_advance() overrides this and it hunts; only when it
	 * cannot does it actually walk home. */
	if (dist > radius) {
		mon->target.grid = mon->home;
		mflag_on(mon->mflag, MFLAG_TRACKING);
		return true;
	}

	return false;
}
/* HITHER-LANDS:eco-home-leash END */

