/* HITHER-LANDS:eco-aid-fn BEGIN */
/*
 * Mutual aid: when a group monster is struck by the player, its packmates
 * within earshot rally to its defence - waking, turning hostile, and heading
 * for the commotion.  This re-arms the group cohesion the eco-* awake-fauna
 * layer removed: monster_group_rouse() only wakes *sleeping* friends, and
 * fauna no longer sleep.  Bounded to the monster's own group and to its
 * hearing range, so it never cascades across the level.
 */
static void hl_group_call_to_arms(struct monster *mon)
{
	int index = mon->group_info[PRIMARY_GROUP].index;
	struct monster_group *group;
	struct mon_group_list_entry *entry;

	/* Solo monsters have nobody to call. */
	if (index <= 0) return;
	group = cave->monster_groups[index];
	if (!group) return;

	for (entry = group->member_list; entry; entry = entry->next) {
		struct monster *friend = cave_monster(cave, entry->midx);

		if (!friend || friend == mon || !friend->race) continue;

		/* Never turn the player's own allies/followers against them. */
		if (friend->target.midx > 0) continue;
		if (mflag_has(friend->mflag, MFLAG_FOLLOWER)) continue;

		/* Already answering the call. */
		if (friend->target.midx == -1 &&
			mflag_has(friend->mflag, MFLAG_AWARE)) continue;

		/* Only packmates within earshot of the commotion respond. */
		if (distance(mon->grid, friend->grid) > mon->race->hearing) continue;

		/* Answer: wake, turn hostile, and head for the cry. */
		friend->target.midx = -1;
		monster_wake(friend, false, 100);
		friend->target.grid = mon->grid;
		mflag_on(friend->mflag, MFLAG_TRACKING);
		mflag_on(friend->mflag, MFLAG_RALLIED);
	}
}
/* HITHER-LANDS:eco-aid-fn END */

