/**
 * HITHER-LANDS:help-tile-code
 * Inline tile plates for help files.  Cells to be redrawn as tiles are
 * listed in lib/help/help-tiles.idx, generated by the Hither Lands build:
 *     <help file>|<hash of the line>|<column>|<attr>|<char>
 * The line's own text is the key, so the index survives renumbering and
 * needs no knowledge of which lines the browser counts as "real".
 */
#define HELP_TILE_MAX 1024

struct help_tile_cell {
	unsigned int hash;
	int col;
	int a;
	int c;
};

static struct help_tile_cell help_tile_cells[HELP_TILE_MAX];
static int help_tile_count = 0;

static unsigned int help_tile_hash(const char *str)
{
	unsigned int h = 2166136261u;

	while (*str) {
		h ^= (unsigned char) *str++;
		h *= 16777619u;
	}

	return h;
}

static void help_tile_load(const char *name)
{
	char path[1024];
	char buf[1024];
	ang_file *fh;

	help_tile_count = 0;

	/* Tiles exist only in a graphical front end */
	if (use_graphics == GRAPHICS_NONE) return;

	/* ...and only under OUR tileset. help-tiles.idx holds Hither Lands
	 * atlas coordinates; under another tileset those same coordinates
	 * address unrelated art, so the plates would draw arbitrary wrong
	 * tiles into the help text. */
	if (!current_graphics_mode
			|| !(streq(current_graphics_mode->menuname, "Hither Lands")
				|| suffix(current_graphics_mode->path, "fa-ai")
				|| suffix(current_graphics_mode->path, "fa-ai/"))) {
		return;
	}

	path_build(path, sizeof(path), ANGBAND_DIR_HELP, "help-tiles.idx");
	fh = file_open(path, MODE_READ, FTYPE_TEXT);
	if (!fh) return;

	while (file_getl(fh, buf, sizeof(buf))) {
		char *field[5];
		char *cur = buf;
		int n = 0;

		if (buf[0] == '#' || buf[0] == '\0') continue;

		while (n < 5) {
			field[n++] = cur;
			cur = strchr(cur, '|');
			if (!cur) break;
			*cur++ = '\0';
		}

		if (n < 5) continue;
		if (!streq(field[0], name)) continue;
		if (help_tile_count >= HELP_TILE_MAX) break;

		help_tile_cells[help_tile_count].hash =
			(unsigned int) strtoul(field[1], NULL, 16);
		help_tile_cells[help_tile_count].col = atoi(field[2]);
		help_tile_cells[help_tile_count].a = atoi(field[3]);
		help_tile_cells[help_tile_count].c = atoi(field[4]);
		help_tile_count++;
	}

	file_close(fh);
}

static void help_tile_line(const char *text, int row)
{
	unsigned int hash;
	int i;

	if (!help_tile_count) return;

	hash = help_tile_hash(text);

	for (i = 0; i < help_tile_count; i++) {
		if (help_tile_cells[i].hash != hash) continue;

		Term_queue_char(Term, help_tile_cells[i].col, row,
						help_tile_cells[i].a,
						(wchar_t) help_tile_cells[i].c, 0, 0);
	}
}

