/**
 * HITHER-LANDS:help-key-code
 * Expand {key:<command description>} tokens in help text to the key THIS
 * reader's keyset uses.  The lookup walks the same cmd_info tables the game
 * dispatches on, so the help can never drift from the bindings, and it is
 * done at display time, so toggling rogue_like_commands changes the help.
 */
static bool help_key_lookup(const char *desc, size_t len, char *out)
{
	int mode = OPT(player, rogue_like_commands) ? 1 : 0;
	int i;

	for (i = 0; cmds_all[i].name; i++) {
		size_t j;

		for (j = 0; j < cmds_all[i].len; j++) {
			const char *d = cmds_all[i].list[j].desc;
			keycode_t code;

			if (!d || strlen(d) != len) continue;
			if (strncmp(d, desc, len)) continue;

			/* An unset roguelike slot falls back to the standard key */
			code = cmds_all[i].list[j].key[mode];
			if (!code) code = cmds_all[i].list[j].key[0];

			/* Anything unprintable is left as the raw token, loudly */
			if (!code || code > 0x7F) return false;

			*out = (char) code;
			return true;
		}
	}

	return false;
}

static void help_key_expand(char *buf, size_t max)
{
	char work[1024];
	char *src = buf;
	size_t n = 0;

	if (!strstr(buf, "{key:")) return;

	while (*src && n < sizeof(work) - 1) {
		if (!strncmp(src, "{key:", 5)) {
			char *end = strchr(src + 5, '}');
			char key;

			if (end && help_key_lookup(src + 5,
									   (size_t) (end - (src + 5)), &key)) {
				work[n++] = key;
				src = end + 1;
				continue;
			}
		}

		work[n++] = *src++;
	}

	work[n] = '\0';
	my_strcpy(buf, work, max);
}

