{
	init_colors(&g_app);

	/* HITHER-LANDS:display-default-tileset BEGIN
	 * Start in tiles, not ASCII. wipe_window() leaves graphics.id at
	 * GRAPHICS_NONE and nothing else ever sets it, so out of the box the
	 * frontend starts in ASCII and the tileset must be found by hand in the
	 * menu bar.
	 *
	 * DEFERRED ON PURPOSE -- do not move this to startup. load_graphics()
	 * only maps tiles via reset_visuals() when character_dungeon is set, so
	 * enabling graphics before a character exists leaves every cell drawing
	 * atlas cell 0,0 and papers the splash screen with one repeated tile.
	 * That is why upstream only lets you switch tilesets at the command
	 * prompt. TERM_XTRA_REACT is the right seam: ui_leave_init() (ui-display.c)
	 * fires it right after reset_visuals() + process_character_pref_files(),
	 * with the character up, and follows it with Term_redraw_all().
	 *
	 * Matched by name, never by id: install.sh registers us in list.txt as
	 * max(existing name:)+1, so the id differs per tree and a literal would
	 * rot. The path check is the fallback if the menu name is retitled -- it
	 * tracks manifest.json's tileset.directory.
	 *
	 * GATED ON character_generated, and that gate is load-bearing: REACT also
	 * fires from init_angband() (ui-init.c) before z_info/f_info exist, where
	 * reset_visuals() segfaults -- measured, signal 11. play_game() sets
	 * character_generated on BOTH paths (savefile_load, or textui_do_birth)
	 * before signalling EVENT_LEAVE_INIT, so this is the first safe pass.
	 * character_dungeon would NOT do: it is still false here for a newly
	 * born character, only true for a loaded save.
	 *
	 * Latches only once it actually acts, so the early init passes are
	 * skipped rather than consumed. REACT also fires from the options menu,
	 * so without the latch a player choosing ASCII would be snapped back to
	 * tiles on the spot. First run decides; after that the choice is theirs. */
	{
		static bool hl_tileset_defaulted = false;

		if (!hl_tileset_defaulted && character_generated
				&& g_app.windows[MAIN_WINDOW].inited) {
			hl_tileset_defaulted = true;

			/* Only for a player who has never configured the frontend.
			 * GRAPHICS_NONE alone is not enough: choosing ASCII SAVES
			 * window-graphics-id:0, so testing only the id would re-force
			 * tiles at every launch and make ASCII unselectable. The
			 * absence of the config file is what actually means "fresh";
			 * the frontend writes it on exit, so this is true exactly
			 * once, for a first run. */
			if (file_exists(g_app.config_file))
				return 0;

			if (g_app.windows[MAIN_WINDOW].graphics.id == GRAPHICS_NONE) {
				graphics_mode *hl_mode;

				for (hl_mode = graphics_modes; hl_mode;
						hl_mode = hl_mode->pNext) {
					if (hl_mode->grafID == GRAPHICS_NONE) {
						continue;
					}
					if (streq(hl_mode->menuname, "Hither Lands")
							|| suffix(hl_mode->path, "fa-ai")
							|| suffix(hl_mode->path, "fa-ai/")) {
						reload_all_graphics(&g_app, hl_mode);
						reset_visuals(true);
						break;
					}
				}
			}
		}
	}
	/* HITHER-LANDS:display-default-tileset END */

