/* HITHER-LANDS:display-lightmode-fwd -- hl_toggle_light_mode is defined far
 * below (right after init_colors, which it calls); handle_key needs it. */
static void hl_toggle_light_mode(void);
/* A stored light-mode:1 choice, read from config; applied once the frontend
 * is up (term_xtra_react). Declared here so term_xtra_react, which is above the
 * toggle's definition, can see it (issue #13 D9). */
static bool hl_light_pending = false;

/* HITHER-LANDS:display-lightmode-fn
 * Runtime light/dark toggle (issue #13 D9; ledger
 * DEC-2026-07-23-pinned-light-dark-toggle). Flips the 32-entry
 * angband_color_table between the loaded dark theme and a light theme derived
 * by a hue-preserving luminance inversion, re-derives the SDL colours and
 * repaints. Defaults OFF; applied ONLY by the explicit F9 toggle, never
 * auto-forced -- display state is the player's (never-regress, PAT-2026-07-22
 * / INC-2026-07-23). Session-only for now; cross-session persistence via a
 * dedicated light-mode: config line is the flagged next step. */
static bool hl_light_mode = false;
static bool hl_dark_saved = false;
static uint8_t hl_dark_table[MAX_COLORS][4];

static void hl_light_of(const uint8_t *dark, uint8_t *out)
{
	/* Additive luminance inversion: shift every channel by (255 - 2*y) so a
	 * colour's luminance y becomes 255 - y. Unlike a multiplicative scale this
	 * lifts pure black (the void, COLOUR_DARK) to white and drops pure white
	 * (text) to black -- guaranteeing legible dark-on-light. Verified against
	 * FAangband's default 32-colour table before landing (issue #13 D9). */
	int r = dark[1], g = dark[2], b = dark[3];
	int y = (30 * r + 59 * g + 11 * b) / 100;
	int delta = 255 - 2 * y;
	int nr = r + delta, ng = g + delta, nb = b + delta;
	out[0] = dark[0];
	out[1] = (uint8_t)(nr < 0 ? 0 : (nr > 255 ? 255 : nr));
	out[2] = (uint8_t)(ng < 0 ? 0 : (ng > 255 ? 255 : ng));
	out[3] = (uint8_t)(nb < 0 ? 0 : (nb > 255 ? 255 : nb));
}

static void hl_apply_light_mode(bool on)
{
	size_t i;
	if (!hl_dark_saved) {
		memcpy(hl_dark_table, angband_color_table, sizeof(hl_dark_table));
		hl_dark_saved = true;
	}
	if (on) {
		for (i = 0; i < (size_t)MAX_COLORS; i++) {
			hl_light_of(hl_dark_table[i], angband_color_table[i]);
		}
	} else {
		memcpy(angband_color_table, hl_dark_table, sizeof(hl_dark_table));
	}
	hl_light_mode = on;
	init_colors(&g_app);
	Term_redraw();
}

static void hl_toggle_light_mode(void)
{
	hl_apply_light_mode(!hl_light_mode);
}

/* HITHER-LANDS:display-lightmode-key: F12 toggles the light/dark colour
 * theme (issue #13 D9), checked on the raw SDL scancode before the Angband
 * key mapping so it collides with no keyset. */
if (key->keysym.scancode == SDL_SCANCODE_F12) {
	hl_toggle_light_mode();
	return true;
}

/* HITHER-LANDS:display-lightmode-readfn */
static enum parser_error config_light_mode(struct parser *parser)
{
	hl_light_pending = (parser_getint(parser, "on") != 0);
	return PARSE_ERROR_NONE;
}

/* HITHER-LANDS:display-lightmode-apply -- apply a stored light-mode choice
 * once the frontend window exists (issue #13 D9). Toggling from the OFF
 * default turns it on; latched so it fires exactly once, never re-forced. */
{
	static bool hl_light_applied = false;
	if (!hl_light_applied && hl_light_pending
			&& g_app.windows[MAIN_WINDOW].inited) {
		hl_light_applied = true;
		hl_toggle_light_mode();
	}
}

/* HITHER-LANDS:town-roof-mark -- flag a town BUILDING wall for the roof
 * tile (issue #13 D6).  Rule: a FEAT_PERM cell is a building wall iff all
 * four cardinal walks reach a non-permanent cell within 6 steps WITHOUT
 * running off the level.  Why that separates buildings from the town's
 * outer wall (town_gen_layout, gen-cave.c):
 *   - a store/home is a solid FEAT_PERM rectangle of at most 5x3, embedded
 *     in floor, so every one of its cells passes (5 wide needs radius 5);
 *     ruins are FEAT_GRANITE, not FEAT_PERM, so they are never eligible;
 *   - the outer wall is everything outside the floor ELLIPSE plus the
 *     level-edge rectangle.  The ellipse is CONVEX, so from any cell
 *     outside it at least one cardinal ray moves away from the centre and
 *     never re-enters floor -- it leaves the level and the walk breaks with
 *     found = false.  CONVEXITY is the invariant here, not band thickness:
 *     the band is only 1-3 cells thick in a 22x66 town.
 * Known gap: the "Angband Dungeon" world carves its town from a starburst
 * room instead, which is NOT convex; a concave neck <= 6 cells wide there
 * could still be roofed.  Town is a TOPOGRAPHY, not depth 0.  Display-only:
 * the real grid stays FEAT_PERM and still blocks. */
if ((int) g->f_idx == FEAT_PERM
		&& level_topography(player->place) == TOP_TOWN) {
	static const int dx[] = {0, 0, -1, 1};
	static const int dy[] = {-1, 1, 0, 0};
	bool enclosed = true;
	int d;
	for (d = 0; d < 4 && enclosed; d++) {
		int s;
		bool found = false;
		for (s = 1; s <= 6; s++) {
			struct loc p = loc(grid.x + dx[d] * s,
							   grid.y + dy[d] * s);
			if (p.x < 0 || p.y < 0 ||
					p.x >= cave->width || p.y >= cave->height)
				break;
			if (!square_isperm(cave, p)) { found = true; break; }
		}
		if (!found) enclosed = false;
	}
	if (enclosed) g->hl_town_building = true;
}

/* HITHER-LANDS:town-roof-render -- draw the roof tile over a town building
 * wall that map_info flagged (g->hl_town_building), but ONLY when our
 * tileset maps the roof feat (feat_x_attr high bit). ASCII and every other
 * tileset leave the bit clear -> normal wall, untouched. No baked atlas
 * coords: the cell comes from the roof feat's own tile mapping. Placed
 * before the (*tap)/(*tcp) save so the roof flows into the transparency
 * layer too (correct minimap priority + SDL2 background). (issue #13 D6) */
if (g->hl_town_building) {
	static int hl_roof_fidx = -2;   /* -2 unresolved, -1 no such feat */
	if (hl_roof_fidx == -2)
		hl_roof_fidx = lookup_feat("town roof");
	if (hl_roof_fidx >= 0
			&& (feat_x_attr[g->lighting][hl_roof_fidx] & 0x80)) {
		a = feat_x_attr[g->lighting][hl_roof_fidx];
		c = feat_x_char[g->lighting][hl_roof_fidx];
	}
}
